module.exports = {
  extends: ['@commitlint/config-conventional'],
  /*
   * Dependabot writes its subject as "Bump <package> from <a> to <b>", which is
   * start-case and fails `subject-case`. That text is generated by the updater,
   * not written by a contributor, and there is no option to lower-case it, so
   * the dependency-bot commits are exempt. Renovate's subjects already pass.
   *
   * `ignores` skips every rule for the matched message; those messages are
   * conventional apart from the case, so nothing else is lost.
   */
  ignores: [
    (message) => /^chore\((deps|actions)\): Bump /.test(message),
  ],
  rules: {
    'type-enum': [2, 'always', [
      'feat',
      'fix',
      'docs',
      'style',
      'refactor',
      'perf',
      'test',
      'chore',
      'ci',
      'build',
      'revert'
    ]],
    'subject-case': [2, 'never', ['sentence-case', 'start-case', 'pascal-case', 'upper-case']],
    'header-max-length': [2, 'always', 100]
  }
};
